import os
import torch
import torch.nn as nn
from dataset.feature_dataset import FeatureDataset, get_feature_dataloader
from models.multimodal_model import (
    MultimodalModel50Percent,
    BERTOnlyBaseline,
    CNNOnlyBaseline,
    ConcatNoBAMBaseline
)

def run_pipeline_check():
    print("=" * 60)
    print("PHASE J & K — PIPELINE VERIFICATION TEST (100 SAMPLES)")
    print("=" * 60)

    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    print(f"Device: {device}")

    # Load 100 samples generated by main_20_percent.py
    img_path = "features/image_features.pt"
    txt_path = "features/text_features.pt"
    lbl_path = "features/labels.pt"

    if not (os.path.exists(img_path) and os.path.exists(txt_path) and os.path.exists(lbl_path)):
        print("Error: 100-sample feature files missing! Running main_20_percent.py first...")
        import subprocess
        subprocess.run(["python", "main_20_percent.py"], check=True)

    img_feats = torch.load(img_path)
    txt_feats = torch.load(txt_path)
    labels = torch.load(lbl_path)

    print(f"Loaded features:")
    print(f"  Visual features shape: {img_feats.shape} (Expected: [100, 2048])")
    print(f"  Textual features shape: {txt_feats.shape} (Expected: [100, 768])")
    print(f"  Labels shape:          {labels.shape} (Expected: [100])")

    # Verify FeatureDataset
    dataset = FeatureDataset(img_feats, txt_feats, labels)
    loader = get_feature_dataloader(img_feats, txt_feats, labels, batch_size=16, shuffle=True)
    print(f"\nDataLoader initialized successfully with {len(dataset)} samples across {len(loader)} batches.")

    # Initialize MultimodalModel50Percent
    model = MultimodalModel50Percent().to(device)
    criterion = nn.CrossEntropyLoss()
    optimizer = torch.optim.Adam(model.parameters(), lr=0.001)

    print("\nTesting Forward Pass, BAM Attention, Loss & Backpropagation...")
    model.train()
    for batch_idx, (b_img, b_txt, b_lbl) in enumerate(loader):
        b_img, b_txt, b_lbl = b_img.to(device), b_txt.to(device), b_lbl.to(device)
        
        optimizer.zero_grad()
        logits, fused_feats, img_attn, txt_attn = model(b_img, b_txt)
        
        loss = criterion(logits, b_lbl)
        loss.backward()
        optimizer.step()

        if batch_idx == 0:
            print(f"  Batch 0 Logits shape:      {logits.shape} (Expected: [16, 2])")
            print(f"  Batch 0 Fused shape:       {fused_feats.shape} (Expected: [16, 512])")
            print(f"  Batch 0 Image Attn shape:  {img_attn.shape} (Expected: [16, 1])")
            print(f"  Batch 0 Text Attn shape:   {txt_attn.shape} (Expected: [16, 1])")
            print(f"  Sample 0 Image Attn Weight: {img_attn[0].item():.4f}")
            print(f"  Sample 0 Text Attn Weight:  {txt_attn[0].item():.4f}")
            print(f"  Batch 0 Loss:              {loss.item():.4f}")

    print("\nForward pass, BAM feature fusion, and backprop check PASSED successfully!")
    print("=" * 60)

if __name__ == "__main__":
    run_pipeline_check()
